package iot

import (
	"net/http"
	"github.com/golang-jwt/jwt/v5"
	"github.com/labstack/echo/v4"
	"myapp/smarthome"
)

type PinPayload struct {
	NewPIN string `json:"new_pin"`
}

type LockController struct {
	LockManager smarthome.LockManager
}

func (ctrl *LockController) UpdatePasscode(c echo.Context) error {
	lockID := c.Param("lockID")
	token := c.Get("user").(*jwt.Token)
	claims := token.Claims.(jwt.MapClaims)
	userID := claims["sub"].(string)

	var body PinPayload
	if err := c.Bind(&body); err != nil {
		return c.JSON(http.StatusBadRequest, echo.Map{"error": "Bad input"})
	}

	err := ctrl.LockManager.SetPINForOwner(c.Request().Context(), lockID, userID, body.NewPIN)
	if err != nil {
		return c.JSON(http.StatusForbidden, echo.Map{"error": "Lock not found or unauthorized"})
	}

	return c.JSON(http.StatusOK, echo.Map{"status": "pin_updated"})
}
